void ckh_rebuild(ckh_t *ckh, ckhc_t *aTab) {
    size_t i, ncells;
    size_t hashes[2];

    if (aTab == NULL || ckh == NULL) {
        return;
    }

    ncells = (ZU(1) << (ckh->lg_curbuckets + LG_CKH_BUCKET_CELLS));
    for (i = 0; i < ncells; i++) {
        if (aTab[i].key != NULL) {
            ckh->hash(aTab[i].key, hashes);
            if (!ckh_try_bucket_insert(ckh, hashes[0] & ((ZU(1) << ckh->lg_curbuckets) - 1), aTab[i].key, aTab[i].data)) {
